// Card data, generated by `pnpm update-cards` into generated/. Stats files
// load on demand, so the browser only downloads the selected server's stats.
import metadata from '../generated/metadata.json' with { type: 'json' };
import { NAME_FIELD, joinCards } from './join-cards.js';

export { metadata };

const STATS = {
  gl: () => import('../generated/global_stats.json', { with: { type: 'json' } }),
  jp: () => import('../generated/jp_stats.json', { with: { type: 'json' } }),
};

const cache = {};
const loadStats = (server) => STATS[server]().then((m) => m.default);

// Same shape and order as upstream's src/cards/gl.js and jp.js arrays.
export function loadCards(server) {
  cache[server] ??= loadStats(server).then((stats) => joinCards(server, metadata, stats));
  return cache[server];
}

// The server's cards plus JP's cards it doesn't have yet, for rankings that look ahead (Global
// releases JP's cards later). Those use JP's stats, which are identical for every card both servers
// have. Their name in the server's language comes from another card of the same character; a new
// character keeps its JP name. On JP itself this is just JP's cards.
export function loadCardsWithUpcoming(server) {
  if (server === 'jp') return loadCards('jp');
  cache[`${server}+upcoming`] ??= Promise.all([loadStats(server), loadStats('jp')]).then(([own, jp]) => {
    const field = NAME_FIELD[server];
    const known = new Map(
      Object.values(metadata)
        .filter((m) => m[field])
        .map((m) => [m.name_jp, m[field]])
    );
    const upcoming = Object.keys(jp).filter((id) => !(id in own));
    const meta = { ...metadata };
    for (const id of upcoming) {
      meta[id] = { ...meta[id], [field]: meta[id][field] ?? known.get(meta[id].name_jp) ?? meta[id].name_jp };
    }
    return joinCards(server, meta, { ...own, ...Object.fromEntries(upcoming.map((id) => [id, jp[id]])) });
  });
  return cache[`${server}+upcoming`];
}
